from web_utils import parse_content_type, image_type


def describe_upload(content_type: str, data: bytes) -> dict[str, Any]:
    """
    Describe an upload based on a Content-Type header and the initial body bytes.

    Returns:
      {
        "mime": lower-cased media type without parameters (e.g. "text/plain"),
        "charset": lower-cased charset parameter (or None),
        "image": one of {"png","jpeg","gif"} or None (detected from signature bytes)
      }
    """
    if _content_type_helper is not None:
        # If available in the environment, use it (it should match the behaviour described).
        mime_lc, params = _content_type_helper(content_type)  # type: ignore[misc]
    else:
        mime_lc, params = parse_content_type(content_type)

    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()

    img = image_type(data)
    if img not in {"png", "jpeg", "gif"}:
        img = None

    return {
        "mime": (mime_lc or "").lower(),
        "charset": charset,
        "image": img,
    }
